import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizeCart } from './cart.mjs';
test('empty cart', () => assert.deepEqual(normalizeCart([]), []));
test('valid line', () => assert.deepEqual(normalizeCart([{sku:'a',quantity:2,unitPriceCents:101}]), [{sku:'a',quantity:2,unitPriceCents:101}]));
